tasks.answer:
weights = [1, 3, 4, 5]
values  = [1, 4, 5, 7]
W, n = 7, 4
dp = [[0] * (W + 1) for _ in range(n + 1)]

for i in range(1, n + 1):
    for w in range(1, W + 1):
        if weights[i - 1] > w:
            dp[i][w] = dp[i - 1][w]
        else:
            dp[i][w] = max(values[i - 1] + dp[i - 1][w - weights[i - 1]], dp[i - 1][w])

for row in dp:
    print(row)
print('최대 가치:', dp[n][W])
